package br.gov.dere.api;
import br.gov.dere.application.certificate.CertificateService; import java.util.*; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/certificates") public class CertificateController {private final CertificateService service;public CertificateController(CertificateService s){service=s;} @GetMapping("/entity/{entityId}") public List<CertificateService.CertificateDto> list(@PathVariable Long entityId){return service.list(entityId);} @PostMapping(value="/entity/{entityId}",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public CertificateService.CertificateDto upload(@PathVariable Long entityId,@RequestPart String label,@RequestPart MultipartFile file,@RequestPart String password)throws Exception{var e=service.save(entityId,label,file,password);return new CertificateService.CertificateDto(e.getId(),e.getLabel(),e.getAliasName(),e.getValidUntil());}}
